function celebrate(){if(document.querySelector('.celebrate'))return;const wrap=document.createElement('div');wrap.className='celebrate';wrap.innerHTML=`<canvas></canvas><div class="celebrate-card"><div class="emoji">🎉</div><h2>Chúc mừng ${esc(state.user?.name||'bạn')}!</h2><p>Bạn đã hoàn thành bài kiểm tra. Cảm ơn bạn đã nỗ lực hết mình ♡<br>Điểm trắc nghiệm đã sẵn sàng, phần tự luận sẽ được QA chấm sớm.</p><button class="btn">Xem kết quả ✿</button></div>`;document.body.appendChild(wrap);const cv=wrap.querySelector('canvas'),ctx=cv.getContext('2d'),dpr=window.devicePixelRatio||1,colors=['#f48fb1','#f06292','#ce93d8','#ffd1dc','#ffb74d','#fff59d','#b39ddb','#ff8a80'];let W,H,parts=[],raf,running=true,launched=0;const size=()=>{W=innerWidth;H=innerHeight;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)};size();addEventListener('resize',size);const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const burst=()=>{const x=W*(.15+Math.random()*.7),y=H*(.12+Math.random()*.4),c=colors[Math.random()*colors.length|0],n=reduce?24:70;for(let i=0;i<n;i++){const a=Math.PI*2*i/n,v=2+Math.random()*4.5;parts.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:1,c:Math.random()<.25?colors[Math.random()*colors.length|0]:c,r:1.6+Math.random()*2})}};const timer=setInterval(()=>{if(launched++>(reduce?3:14)){clearInterval(timer);return}burst();if(!reduce&&Math.random()<.5)burst()},380);burst();const tick=()=>{if(!running)return;ctx.globalCompositeOperation='destination-out';ctx.fillStyle='rgba(0,0,0,.22)';ctx.fillRect(0,0,W,H);ctx.globalCompositeOperation='lighter';parts=parts.filter(p=>p.life>0);for(const p of parts){p.vx*=.985;p.vy=p.vy*.985+.06;p.x+=p.vx;p.y+=p.vy;p.life-=.012;ctx.globalAlpha=Math.max(p.life,0);ctx.fillStyle=p.c;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;raf=requestAnimationFrame(tick)};tick();const close=()=>{running=false;clearInterval(timer);cancelAnimationFrame(raf);removeEventListener('resize',size);wrap.remove()};wrap.querySelector('button').onclick=close;wrap.addEventListener('click',e=>{if(e.target===wrap||e.target===cv)close()});setTimeout(()=>{if(running)close()},12000)}



// Question import: QA review and explicit approval are required before changing the bank.
let pendingQuestionImport=null;
const QUESTION_IMPORT_HEADERS=['Mã câu hỏi','Nhóm nghiệp vụ','Knowledge area','业务模块','Loại câu hỏi','Nội dung câu hỏi','Đáp án A','Đáp án B','Đáp án C','Đáp án D','Đáp án đúng','Giải thích / Tiêu chí chấm','Điểm tối đa'];
function downloadQuestionTemplate(){
 if(!isAdmin())return notice('Chỉ QA được xuất file mẫu');
 const rows=[QUESTION_IMPORT_HEADERS,['Q051','Giao tiếp & xoa dịu','','','Trắc nghiệm','Ví dụ: Khách không hài lòng, cách xử lý phù hợp?','Lắng nghe và ghi nhận','Tranh cãi với khách','Bỏ qua tin nhắn','Đóng chat','A','Ghi nhận phản hồi, không cam kết ngoài quy trình',2],['Q052','QA & quy trình','','','Tự luận','Ví dụ: Viết phản hồi khi khách phản ánh dịch vụ chậm','','','','','','Tiêu chí: đồng cảm, xác minh, theo dõi',2]];
 exportRows(rows,'CSKH_Mau_nhap_ngan_hang_cau_hoi.csv');
}
function parseQuestionCSV(str){
 str=str.replace(/^\uFEFF/,'');let rows=[],row=[],field='',quoted=false;
 for(let i=0;i<str.length;i++){let ch=str[i];if(quoted){if(ch==='"'&&str[i+1]==='"'){field+='"';i++}else if(ch==='"')quoted=false;else field+=ch}
 else if(ch==='"'){if(field.trim()!=='')throw Error('Định dạng dấu nháy không hợp lệ');quoted=true}
 else if(ch===','){row.push(field);field=''}else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&str[i+1]==='\n')i++;row.push(field);if(row.some(c=>c.trim()))rows.push(row);row=[];field=''}else field+=ch;
 }if(quoted)throw Error('File CSV có dấu nháy kép chưa đóng');row.push(field);if(row.some(c=>c.trim()))rows.push(row);return rows;
}
function normalizeImportType(v){v=String(v||'').trim().toLowerCase();return v==='trắc nghiệm'||v==='mcq'?'mcq':v==='tự luận'||v==='essay'?'essay':''}
function mapImportedQuestions(rows){
 if(!rows.length)throw Error('File không có dữ liệu');
 const hdr=rows[0].map(x=>String(x||'').replace(/^\uFEFF/,'').trim());
 const index=QUESTION_IMPORT_HEADERS.map(h=>hdr.indexOf(h));
 const required=[0,1,4,5,10,11,12];if(required.some(j=>index[j]===-1))throw Error('Thiếu cột bắt buộc. Hãy dùng file mẫu hoặc file Xuất ngân hàng câu hỏi.');
 let errors=[],questions=[],seen=new Set();
 rows.slice(1).forEach((r,i)=>{
  const get=j=>index[j]<0?'':String(r[index[j]]??'').trim();
  if(!r.some(v=>String(v||'').trim()))return;
  const id=get(0),category=get(1),type=normalizeImportType(get(4)),question=get(5),options=[get(6),get(7),get(8),get(9)],correct=get(10).toUpperCase(),guide=get(11),points=Number(get(12)||2),bad=[];
  if(!/^[A-Za-z0-9_-]{1,64}$/.test(id))bad.push('mã câu không hợp lệ');
  if(seen.has(id))bad.push('trùng mã câu trong file');seen.add(id);
  if(!CATS.includes(category))bad.push('nhóm nghiệp vụ không nằm trong 9 nhóm');
  if(!type)bad.push('loại câu không hợp lệ');if(!question)bad.push('thiếu nội dung');
  if(points!==2)bad.push('điểm phải bằng 2 để giữ thang điểm 100');
  if(type==='mcq'&&(options.some(x=>!x)||!['A','B','C','D'].includes(correct)))bad.push('cần đủ 4 phương án và đáp án A–D');
  if(type==='essay'&&correct)bad.push('câu tự luận không được có đáp án A–D');
  if(bad.length)errors.push('Dòng '+(i+2)+': '+bad.join(', '));
  else questions.push({id,category,type,question,options:type==='mcq'?options:null,correct:type==='mcq'?'ABCD'.indexOf(correct):null,explanation:type==='mcq'?guide:null,guide:type==='essay'?guide:null,points:2});
 });
 if(!questions.length&&!errors.length)errors.push('Không có câu hỏi nào');
 if(rows.length===51&&!errors.length){const mcq=questions.filter(x=>x.type==='mcq').length;if(mcq!==45)errors.push('Bộ đề 50 câu cần 45 trắc nghiệm và 5 tự luận');}
 return {questions,errors};
}
async function prepareQuestionImport(file){
 pendingQuestionImport=null;if(!isAdmin())return notice('Chỉ QA được nhập câu hỏi');if(!file)return;
 const el=$('#importPreview');if(file.size>4*1024*1024){el.innerHTML='<div class="notice error">File vượt quá 4 MB.</div>';return}
 try{
 let rows;if(/\.csv$/i.test(file.name))rows=parseQuestionCSV(await file.text());
 else if(/\.(xlsx|xls)$/i.test(file.name)){
  if(!window.XLSX)throw Error('Chưa tải được thư viện đọc Excel. Hãy lưu Excel thành CSV UTF-8 rồi nhập lại.');
  const wb=XLSX.read(await file.arrayBuffer(),{type:'array'});rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:'',raw:false});
 }else throw Error('Chỉ hỗ trợ CSV, XLSX hoặc XLS');
 const {questions,errors}=mapImportedQuestions(rows),old=new Map(state.qs.map(q=>[q.id,q]));
 const changed=questions.filter(q=>old.has(q.id)&&JSON.stringify(({sort_order,...a})=>a)(q)!=='__never__');
 const additions=questions.filter(q=>!old.has(q.id));
 const modified=questions.filter(q=>old.has(q.id)&&['category','type','question','options','correct','explanation','guide','points'].some(k=>JSON.stringify(q[k]??null)!==JSON.stringify(old.get(q.id)[k]??null)));
 pendingQuestionImport=errors.length?null:questions;
 el.innerHTML=`<div class="import-box"><h3>Kiểm tra file: ${esc(file.name)}</h3><div class="import-stats"><span>${questions.length} câu hợp lệ</span><span>${additions.length} câu mới</span><span>${modified.length} câu cập nhật</span><span>${errors.length} lỗi</span></div>${errors.length?`<div class="notice error">${errors.slice(0,15).map(esc).join('<br>')}${errors.length>15?'…':''}</div>`:`<div class="notice">File hợp lệ. Các câu hiện có khác ID sẽ được giữ lại, câu cùng ID được cập nhật. KHÔNG thay đổi dữ liệu bài thi đã nộp.</div><div class="scroll" style="max-height:240px"><table><tr><th>Mã</th><th>Thay đổi</th><th>Nội dung</th></tr>${[...additions.map(q=>[q,'Thêm mới']),...modified.map(q=>[q,'Cập nhật'])].slice(0,20).map(([q,kind])=>`<tr><td>${esc(q.id)}</td><td>${kind}</td><td>${esc(q.question).slice(0,95)}</td></tr>`).join('')}</table></div>`}<div class="toolbar" style="margin-top:12px"><button class="btn" onclick="confirmQuestionImport()" ${errors.length?'disabled':''}>Xác nhận cập nhật</button><button class="ghost" onclick="cancelQuestionImport()">Hủy</button></div></div>`;
 }catch(e){el.innerHTML='<div class="notice error">Không đọc được file: '+esc(e.message)+'</div>'}
 finally{const input=$('#questionImportFile');if(input)input.value=''}
}
function cancelQuestionImport(){pendingQuestionImport=null;let el=$('#importPreview');if(el)el.innerHTML=''}
async function confirmQuestionImport(){
 if(!isAdmin()||!pendingQuestionImport?.length)return notice('Chưa có file hợp lệ');
 const questions=pendingQuestionImport,old=state.qs.slice(),oldIds=new Map(old.map((q,i)=>[q.id,i]));
 if(!confirm(`Cập nhật ${questions.length} câu hỏi vào ${state.mode==='cloud'?'Supabase':'Demo trên máy'}? Hãy xuất CSV sao lưu trước khi tiếp tục.`))return;
 try{
  if(state.client){
   const payload=questions.map((q,i)=>({...q,sort_order:oldIds.has(q.id)?oldIds.get(q.id)+1:old.length+1+i}));
   // Batch upsert, but no claimed transaction across batches.
   for(let i=0;i<payload.length;i+=50){const {error}=await state.client.from('questions').upsert(payload.slice(i,i+50),{onConflict:'id'});if(error)throw error}
   await refreshCloud();
  }else{for(let q of questions){const idx=state.qs.findIndex(x=>x.id===q.id);if(idx<0)state.qs.push(q);else state.qs[idx]=q}saveLocal()}
  pendingQuestionImport=null;notice('Đã nhập câu hỏi thành công');render();
 }catch(e){notice('Nhập chưa hoàn tất: '+e.message+' — hãy đồng bộ và kiểm tra lại, không nhập lặp khi chưa kiểm tra')}
}


// === V4: monthly exam plans, publish workflow & reporting ===
function availableMonths(){return [...new Set(state.attempts.map(a=>String(a.exam_month||monthKey(a.started_at)).slice(0,7)))].sort().reverse()}
function filteredMonthlyAttempts(){return state.attempts.filter(a=>a.status==='submitted'&&(state.reportMonth==='all'||String(a.exam_month||monthKey(a.started_at)).slice(0,7)===state.reportMonth))}
function setReportMonth(v){state.reportMonth=v;render()}
function monthPicker(){return `<label style="margin:0">Kỳ thi <select onchange="setReportMonth(this.value)"><option value="all">Tất cả các tháng</option>${availableMonths().map(m=>`<option value="${m}" ${state.reportMonth===m?'selected':''}>${m}</option>`).join('')}</select></label>`}
function monthlyComparison(){let months=availableMonths();if(!months.length)return '<p class="muted small">Chưa có bài thi đã nộp. Thống kê sẽ hiển thị sau kỳ đầu tiên.</p>';return `<div class="scroll"><table><tr><th>Tháng</th><th>Bài nộp</th><th>Đã chấm</th><th>Điểm TB</th><th>Tỷ lệ đạt</th></tr>${months.map(m=>{let arr=state.attempts.filter(a=>a.status==='submitted'&&String(a.exam_month||monthKey(a.started_at)).slice(0,7)===m),graded=arr.filter(a=>a.total_score!=null);return `<tr><td>${m}</td><td>${arr.length}</td><td>${graded.length}</td><td>${graded.length?(graded.reduce((s,a)=>s+Number(a.total_score),0)/graded.length).toFixed(1):'—'}</td><td>${graded.length?pct(100*graded.filter(a=>a.total_score>=80).length/graded.length):'—'}</td></tr>`}).join('')}</table></div>`}
function nextMonth(){let d=new Date();return new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,1)).toISOString().slice(0,7)}
function renderExamSets(){if(!isAdmin())return '<p>Chỉ QA có quyền quản lý bộ đề.</p>';let sets=state.examSets||[];let chosen=state.selectedExamIds.length?state.selectedExamIds:state.qs.map(q=>q.id).slice(0,50);return `<div class="panel"><h2>Bộ đề theo tháng</h2><p class="muted small">Nhập Excel/CSV ở mục Ngân hàng câu hỏi trước, sau đó chọn đúng 45 trắc nghiệm và 5 tự luận tại đây. Chỉ bộ đề đã công bố mới được dùng trong kỳ thi tương ứng. Không sửa câu hỏi sau khi công bố.</p><div class="formgrid"><div><label>Tháng áp dụng</label><input type="month" id="planMonth" value="${nextMonth()}"></div><div><label>Tên bộ đề</label><input id="planName" value="Bài kiểm tra CSKH định kỳ" maxlength="120"></div></div><div class="toolbar" style="margin:14px 0"><button class="ghost" onclick="selectInitialExamSet()">Chọn 45 trắc nghiệm + 5 tự luận đầu tiên</button><button class="btn" onclick="saveExamPlan()">Lưu bộ đề nháp</button></div><div class="notice">Đã chọn: <b id="selectedSummary">${chosen.length}</b> câu. Mỗi bộ đề phải đúng 45 trắc nghiệm + 5 tự luận.</div><div class="exam-question-list">${state.qs.map(q=>`<label class="exam-q"><input type="checkbox" class="exam-choice" value="${esc(q.id)}" ${chosen.includes(q.id)?'checked':''} onchange="setExamChoices()"><span><b>${esc(q.id)}</b> · ${q.type==='mcq'?'Trắc nghiệm':'Tự luận'} · ${esc(q.category)}<br>${esc(q.question)}</span></label>`).join('')}</div></div><div class="panel"><h2>Kỳ thi đã lưu</h2><div class="scroll"><table><tr><th>Tháng</th><th>Tên</th><th>Số câu</th><th>Trạng thái</th><th>Thao tác</th></tr>${sets.map(x=>`<tr><td>${esc(String(x.exam_month).slice(0,7))}</td><td>${esc(x.title)}</td><td>${Array.isArray(x.question_ids)?x.question_ids.length:'—'}</td><td><span class="tag ${x.status==='published'?'green':'orange'}">${x.status==='published'?'Đã công bố':'Bản nháp'}</span></td><td>${x.status==='draft'?`<button class="ghost" onclick="loadExamPlan('${x.id}')">Sửa</button> <button class="btn" onclick="publishExamPlan('${x.id}')">Duyệt & công bố</button>`:'Khóa chỉnh sửa'}</td></tr>`).join('')}</table></div></div>`}
function setExamChoices(){state.selectedExamIds=[...document.querySelectorAll('.exam-choice:checked')].map(x=>x.value);const el=$('#selectedSummary');if(el)el.textContent=state.selectedExamIds.length}
function selectInitialExamSet(){state.selectedExamIds=[...state.qs.filter(q=>q.type==='mcq').slice(0,45),...state.qs.filter(q=>q.type==='essay').slice(0,5)].map(q=>q.id);render()}
function loadExamPlan(id){let x=state.examSets.find(a=>a.id===id);if(!x||x.status!=='draft')return;state.selectedExamIds=x.question_ids;render();$('#planMonth').value=String(x.exam_month).slice(0,7);$('#planName').value=x.title}
async function saveExamPlan(){if(!isAdmin())return;setExamChoices();const arr=state.selectedExamIds.map(id=>state.qs.find(q=>q.id===id)),month=$('#planMonth').value,title=$('#planName').value.trim();if(!/^\d{4}-\d{2}$/.test(month)||!title)return notice('Nhập tháng và tên kỳ thi');if(arr.includes(undefined)||arr.length!==50||arr.filter(q=>q.type==='mcq').length!==45||arr.filter(q=>q.type==='essay').length!==5)return notice('Bộ đề phải gồm đúng 45 trắc nghiệm và 5 tự luận');let exists=state.examSets.find(x=>String(x.exam_month).slice(0,7)===month);if(exists?.status==='published')return notice('Kỳ thi đã công bố, không thể chỉnh sửa');let payload={exam_month:month+'-01',title,question_ids:state.selectedExamIds,status:'draft'};try{if(state.client){let r=await state.client.from('exam_sets').upsert(exists?{...payload,id:exists.id}:payload,{onConflict:'exam_month'}).select().single();if(r.error)throw r.error;await refreshCloud()}else{state.examSets=state.examSets.filter(x=>String(x.exam_month).slice(0,7)!==month);state.examSets.push({...payload,id:exists?.id||ID()});saveLocal()}notice('Đã lưu bản nháp kỳ thi');render()}catch(e){notice('Không lưu được: '+e.message)}}
async function publishExamPlan(id){let x=state.examSets.find(e=>e.id===id);if(!x||!confirm(`Công bố bộ đề tháng ${String(x.exam_month).slice(0,7)}? Sau khi công bố không thể chỉnh sửa bộ đề.`))return;try{if(state.client){let r=await state.client.rpc('qa_publish_exam_set',{p_set_id:id});if(r.error)throw r.error;await refreshCloud()}else{x.status='published';saveLocal()}notice('Đã công bố bộ đề');render()}catch(e){notice('Không thể công bố: '+e.message)}}
